// test_dynmatch.cpp — M1 gate for the C++ port.
//
// Three layers (documented differential strategy):
//  1. Edge-case unit tests mirroring the Python suite's deterministic tests.
//  2. In-process differential vs a SLOW-BUT-OBVIOUSLY-CORRECT brute-force
//     maximum-matching oracle (bitmask recursion over vertex subsets,
//     memoized; n <= 10). Independent of the blossom kernel by construction.
//  3. Cross-language golden replay: ops generated by cpp/tests/gen_golden.py
//     (dynamic.py + networkx cross-verified), replayed here; the size after
//     EVERY op must match the Python/networkx value exactly.
#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <random>
#include <sstream>
#include <string>
#include <vector>

#include "dynmatch/dynmatch.h"

using dm::DynamicMatching;

static int failures = 0;
#define CHECK(cond)                                                     \
    do {                                                                \
        if (!(cond)) {                                                  \
            ++failures;                                                 \
            std::fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, \
                         #cond);                                        \
        }                                                               \
    } while (0)

// ------------------------------------------------------------ brute oracle

struct BruteOracle {
    int n;
    std::vector<std::vector<int32_t>> adj;
    std::vector<int16_t> memo;

    explicit BruteOracle(int n_) : n(n_), adj(n_) { memo.assign(1u << n, -1); }

    int solve(uint32_t avail) {
        if (avail == 0) return 0;
        if (memo[avail] >= 0) return memo[avail];
        const int v = __builtin_ctz(avail);
        int best = solve(avail & ~(1u << v));  // leave v unmatched
        for (int32_t u : adj[v])
            if ((avail >> u) & 1u)
                best = std::max(best, 1 + solve(avail & ~((1u << v) | (1u << u))));
        memo[avail] = static_cast<int16_t>(best);
        return best;
    }
};

// ---------------------------------------------------------------- unit tests

static void test_edge_cases() {
    {
        DynamicMatching dm(0);
        CHECK(dm.size() == 0 && dm.matching().empty() && dm.is_valid());
    }
    {
        DynamicMatching dm(1);
        CHECK(dm.size() == 0);
    }
    {
        DynamicMatching dm(2);
        dm.insert(0, 1);
        CHECK(dm.size() == 1);
        auto m = dm.matching();
        CHECK(m.size() == 1 && m[0].first == 0 && m[0].second == 1);
        dm.remove(0, 1);
        CHECK(dm.size() == 0 && dm.is_valid());
    }
    bool threw = false;
    try { DynamicMatching dm(3); dm.insert(1, 1); }
    catch (const std::invalid_argument&) { threw = true; }
    CHECK(threw);
    threw = false;
    try { DynamicMatching dm(3); dm.insert(0, 3); }
    catch (const std::out_of_range&) { threw = true; }
    CHECK(threw);
    threw = false;
    try { DynamicMatching dm(3); dm.remove(-1, 2); }
    catch (const std::out_of_range&) { threw = true; }
    CHECK(threw);
    {  // duplicate insert noop (either order)
        DynamicMatching dm(4);
        dm.insert(0, 1);
        auto r = dm.insert(1, 0);
        CHECK(std::strcmp(r.op, "noop") == 0 && dm.size() == 1);
    }
    {  // delete absent noop
        DynamicMatching dm(4);
        dm.insert(0, 1);
        dm.remove(2, 3);
        dm.remove(0, 2);
        CHECK(dm.size() == 1 && dm.is_valid());
    }
    {  // path graph: nu drop on matched delete
        DynamicMatching dm(3);
        dm.insert_many({{0, 1}, {1, 2}});
        CHECK(dm.size() == 1);
        auto r = dm.remove(1, 2);  // present, unmatched: zero work
        CHECK(!r.searched && r.work == 0 && dm.size() == 1);
        r = dm.remove(0, 1);  // matched; no re-augmentation available
        CHECK(r.nu_dropped && dm.size() == 0);
    }
    {  // 4-path re-augment on matched delete
        DynamicMatching dm(4);
        dm.insert_many({{0, 1}, {1, 2}, {2, 3}, {0, 3}});
        dm.remove(1, 2);
        CHECK(dm.size() == 2);
    }
    {  // interior-of-path insertion augments (spec worked example)
        DynamicMatching dm(6);
        dm.insert_many({{1, 2}, {3, 4}, {0, 1}, {3, 5}});
        CHECK(dm.size() == 2);
        dm.insert(2, 4);
        CHECK(dm.size() == 3);
    }
    {  // complete graphs reach (n-1)/2
        for (int32_t n : {5, 7, 9}) {
            DynamicMatching dm(n);
            for (int32_t u = 0; u < n; ++u)
                for (int32_t v = u + 1; v < n; ++v) dm.insert(u, v);
            CHECK(dm.size() == (n - 1) / 2);
            CHECK(dm.is_valid());
        }
    }
    {  // free vertices
        DynamicMatching dm(5);
        dm.insert(0, 1);
        auto f = dm.free_vertices();
        CHECK(f.size() == 3);
    }
    {  // report/stats sanity
        DynamicMatching dm(6);
        auto r = dm.insert(0, 1);
        CHECK(r.augmented && !r.searched && r.size == 1);
        r = dm.remove(0, 2);
        CHECK(std::strcmp(r.op, "noop") == 0);
        CHECK(dm.stats.updates == 1);
    }
}

// ------------------------------------------- differential vs brute oracle

// Random churn on small graphs (blossom country); after EVERY op the C++
// matching size must equal the brute-force maximum and is_valid must hold.
// `present` is the ground-truth edge set fed to the oracle.
static void churn_differential(int n, int steps, uint32_t seed) {
    std::mt19937 rng(seed);
    DynamicMatching dm(n);
    BruteOracle oracle(n);
    std::vector<std::pair<int32_t, int32_t>> present;
    auto has = [&](int32_t u, int32_t v) {
        return std::find(present.begin(), present.end(),
                         std::make_pair(std::min(u, v), std::max(u, v))) !=
               present.end();
    };
    for (int step = 0; step < steps; ++step) {
        const bool want_ins =
            present.empty() || (rng() % 100 < 55);  // insert bias, like Python suite
        if (want_ins) {
            const int32_t u = rng() % n, v = rng() % n;
            if (u == v || has(u, v)) continue;
            dm.insert(u, v);
            present.emplace_back(std::min(u, v), std::max(u, v));
        } else {
            const int32_t idx = rng() % static_cast<int32_t>(present.size());
            auto e = present[idx];
            dm.remove(e.first, e.second);
            present.erase(present.begin() + idx);
        }
        CHECK(dm.is_valid());
        for (auto& a : oracle.adj) a.clear();
        std::fill(oracle.memo.begin(), oracle.memo.end(), -1);
        for (auto& e : present) {
            oracle.adj[e.first].push_back(e.second);
            oracle.adj[e.second].push_back(e.first);
        }
        const int expect = oracle.solve((1u << n) - 1);
        if (dm.size() != expect) {
            ++failures;
            std::fprintf(stderr,
                         "FAIL differential n=%d seed=%u step=%d: dm=%d "
                         "oracle=%d\n",
                         n, seed, step, dm.size(), expect);
            return;
        }
    }
}

// ------------------------------------------------------ golden replay

static void golden_replay(const std::string& path) {
    std::ifstream in(path);
    if (!in) {
        ++failures;
        std::fprintf(stderr, "FAIL cannot open golden %s\n", path.c_str());
        return;
    }
    DynamicMatching dm(30);
    std::string line;
    int ops = 0;
    while (std::getline(in, line)) {
        if (line.empty()) continue;
        std::istringstream ss(line);
        char op;
        int32_t u, v, expect;
        ss >> op >> u >> v >> expect;
        if (op == 'i') dm.insert(u, v);
        else dm.remove(u, v);
        ++ops;
        if (!dm.is_valid()) {
            ++failures;
            std::fprintf(stderr, "FAIL golden %s op %d: invalid matching\n",
                         path.c_str(), ops);
            return;
        }
        if (dm.size() != expect) {
            ++failures;
            std::fprintf(stderr,
                         "FAIL golden %s op %d (%c %d %d): cpp=%d python=%d\n",
                         path.c_str(), ops, op, u, v, dm.size(), expect);
            return;
        }
    }
    std::printf("golden %s: %d ops OK\n", path.c_str(), ops);
}

int main(int argc, char** argv) {
    test_edge_cases();

    // small-graph churn, many seeds (mirrors the Python suite's shape)
    for (uint32_t seed = 0; seed < 60; ++seed)
        churn_differential(4 + static_cast<int>(seed % 4), 300, seed);

    // a couple of denser runs
    for (uint32_t seed = 100; seed < 105; ++seed)
        churn_differential(9, 300, seed);

    // golden fixtures (paths passed by CMake-defined or argv-provided dir)
    std::string gdir = (argc > 1) ? argv[1] : std::string(GOLDEN_DIR);
    for (int s = 0; s < 5; ++s)
        golden_replay(gdir + "/seed" + std::to_string(s) + ".txt");

    if (failures) {
        std::fprintf(stderr, "%d failure(s)\n", failures);
        return 1;
    }
    std::printf("all tests passed\n");
    return 0;
}
